themeCSS:
.node rect {
  rx: 10px;
  ry: 10px;
  filter: none;
}
.cluster rect {
  rx: 14px;
  ry: 14px;
  filter: none;
}
.nodeLabel {
  font-weight: 500;
}
.cluster-label {
  font-weight: 600;
}
.edgeLabel {
  color: #475569;
  font-size: 14px;
}

.node.frontend rect { fill: #064e3b; stroke: #34d399; } .node.frontend .nodeLabel { color: #d1fae5; }
.node.runtime rect { fill: #172554; stroke: #60a5fa; } .node.runtime .nodeLabel { color: #dbeafe; }
.node.library rect { fill: #2e1065; stroke: #a78bfa; } .node.library .nodeLabel { color: #ede9fe; }
.node.source rect { fill: #1e293b; stroke: #64748b; } .node.source .nodeLabel { color: #e2e8f0; }
.node.tool rect { fill: #422006; stroke: #fbbf24; } .node.tool .nodeLabel { color: #fef3c7; }
.node.artifact rect { fill: #064e3b; stroke: #34d399; } .node.artifact .nodeLabel { color: #d1fae5; }
.edgeLabel { color: #cbd5e1 !important; } .cluster-label span { color: #e2e8f0 !important; }
